          // Focus first invalid field
          if (validationErrors.name && nameRef.current) {
            nameRef.current.focus();
          } else if (validationErrors.email && emailRef.current) {
            emailRef.current.focus();
          } else if (validationErrors.phone && phoneRef.current) {
            phoneRef.current.focus();
          }
          setSubmitStatus('');
        } else {
          // Success
          setSubmitStatus('Message sent successfully. We will get back to you soon.');
          // In a real app we'd send the data to a server here
        }
      };

      const hasNameError = touched.name && errors.name;
