              <input
                id="name"
                name="name"
                type="text"
                required
                autoComplete="name"
                value={formData.name}
                onChange={handleChange}
                onBlur={handleBlur}
                ref={nameRef}
                aria-invalid={hasNameError ? "true" : undefined}
                aria-describedby={hasNameError ? "name-error" : undefined}
              />
              {hasNameError && (
                <p id="name-error" className="error-text">
                  {errors.name}
                </p>
              )}
            </div>

