              <label htmlFor="email">
                Email Address <span className="required-marker" aria-hidden="true">*</span>
              </label>
              <input
                id="email"
                name="email"
                type="email"
                required
                autocomplete="email"
                value={formData.email}
                onChange={handleChange}
                onBlur={handleBlur}
                ref={emailRef}
                aria-invalid={hasEmailError ? "true" : undefined}
                aria-describedby={hasEmailError ? "email-error" : undefined}
              />
              {hasEmailError && (
                <p id="email-error" className="error-text">
                  {errors.email}
                </p>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">
                Phone Number (optional)
              </label>
              <input
                id="phone"
                name="phone"
                type="tel"
                autocomplete="tel"
                value={formData.phone}
                onChange={handleChange}
                onBlur={handleBlur}
                ref={phoneRef}
                aria-invalid={hasPhoneError ? "true" : undefined}
                aria-describedby={`phone-help${hasPhoneError ? ' phone-error' : ''}`}
              />
              <p id="phone-help" className="help-text">
